import json, hashlib, datetime, pathlib
P = pathlib.Path(__file__).resolve().parents[1]
r = {'round': 'R2', 'frozen_utc': datetime.datetime.now(datetime.timezone.utc).isoformat(), 'capability': 'Return a calibrated set of plausible clinician categories, preserving within-patient disagreement rather than a forced single diagnosis', 'obstacle': 'A first-reference-only label hides contradictory reports; a correct geometry prediction may disagree with a different clinician description', 'changed_operation': 'Calibration observation is patient-level max nonconformity over every readable IOS report; one set must cover all stated alternatives', 'consumer': 'Research lab triage of fields needing tooth landmarks or human remeasurement', 'equation': 's_i=max_{y in all parsed patient reports}(1-p_model(y|scan)); q=ceil((n_cal+1)*0.9)-th smallest s_i; S(x)={y:1-p_model(y|x)<=q}. Score=1 for a label absent from training classes; absent classes can remain uncovered even q=1.', 'alpha': 0.1, 'primary_gate': {'all_report_patient_coverage_min': 0.85, 'macro_mean_set_size_max': 2.0, 'macro_singleton_fraction_min': 0.2, 'min_test_patients_per_field': 40, 'tolerance': 1e-12, 'decision': 'All three macro criteria plus per-field test n and R1 parser gate required; per-field failures preserved'}, 'control': 'First-report split conformal, same p and calibration patients; receives entire report list but ordinary target is selected first reference', 'strongest_equally_informed_control': 'Standard split conformal on patient-maximum scores over same reports; algebraically identical candidate, actually executed using independently sorted scores; TIE expected', 'falsifier': 'Broad uninformative sets, low simultaneous coverage, zero singleton decisions, or any score/order-statistic mismatch; injected q=-0.01 must produce empty sets and fail coverage', 'full_cost': {'preparation': 'Existing R1 scans/models reused, entire upstream cost still charged', 'fit': 'No additional model fit', 'discovery': 'Design and code time UNKNOWN', 'validation': 'Read extra local reports and score patient sets; timed', 'questions': 'No new lab/human queries', 'fallback': 'Unidentifiable tooth landmarks UNKNOWN; explicit abstention or >1 categories'}, 'external_referent': {'kind': 'independent_measurement', 'locator': json.load(open(P / 'raw/DATA_MANIFEST.json'))['zip'] + '::*/reports_ios_en/*.txt', 'compared_quantity': 'Simultaneous categorical coverage of all readable independent clinician descriptions per held-out patient; report author IDs unavailable', 'refutes_us': True}, 'assumptions': {'exchangeability': 'UNKNOWN across centers and collection protocols; deterministic hash split approximates exchangeability, no guaranteed clinical deployment coverage', 'labels': 'Parser-derived categorical source judgments, not a mm gold standard', 'rater_independence': 'UNKNOWN; multiple reports clustered by patient, identity not inferred'}}
p = P / 'PREREG_R2.json'
if p.exists():
    raise RuntimeError('Already frozen')
p.write_text(json.dumps(r, indent=2) + '\n')
p.with_suffix('.json.sha256').write_text(hashlib.sha256(p.read_bytes()).hexdigest() + '\n')
